-- Recetas 
INSERT INTO "Recetas"
    ("Titulo", "Descripcion", "Instrucciones", "TiempoMinutos", "FotoPrincipal",
     "FechaDeLaReceta", "MeGustas", "UsuarioID", "CategoriaID")
SELECT r.titulo, r.descripcion, r.instrucciones, r.tiempo, r.foto,
       now() - r.hace, r.megustas, u."Id", c."ID"
FROM (VALUES
    ('Panqueques con miel',
     'Panqueques esponjosos para un desayuno en familia.',
     E'1. Mezclar la harina, el azúcar y la sal.\n2. Agregar los huevos y la leche y batir hasta que no queden grumos.\n3. Cocinar en sartén con manteca, una porción a la vez.\n4. Servir con miel.',
     20, '/imagenes/panqueques.jpg', interval '30 days', 14, 'maria@sabornet.com', 'Desayunos'),

    ('Tostadas de palta y huevo',
     'Un desayuno rápido, sano y lleno de energía.',
     E'1. Tostar el pan.\n2. Pisar la palta con sal y aceite de oliva.\n3. Cocinar los huevos a la plancha.\n4. Armar las tostadas con la palta y el huevo encima.',
     10, '/imagenes/tostadas.jpg', interval '25 days', 9, 'juan@sabornet.com', 'Desayunos'),

    ('Milanesas al horno',
     'Milanesas crocantes sin fritura, ideales para toda la semana.',
     E'1. Pasar los bifes por huevo batido y luego por pan rallado.\n2. Colocar en una placa con aceite de oliva.\n3. Hornear a 200 °C durante 25 minutos, dando vuelta a la mitad.\n4. Servir con ensalada.',
     45, '/imagenes/milanesas.jpg', interval '20 days', 22, 'juan@sabornet.com', 'Almuerzos'),

    ('Pasta con salsa de tomate',
     'Clásico de todos los días con salsa casera.',
     E'1. Hervir los fideos en agua con sal.\n2. Saltear la cebolla en aceite de oliva.\n3. Agregar los tomates picados y cocinar 15 minutos.\n4. Mezclar con los fideos y decorar con albahaca.',
     25, '/imagenes/pasta.jpg', interval '18 days', 17, 'lucia@sabornet.com', 'Almuerzos'),

    ('Tarta de acelga',
     'Tarta casera rellena de acelga y huevo.',
     E'1. Hervir y escurrir la acelga.\n2. Saltear con cebolla.\n3. Mezclar con huevos y mozzarella.\n4. Rellenar la masa y hornear 35 minutos a 180 °C.',
     60, '/imagenes/tarta.jpg', interval '15 days', 11, 'maria@sabornet.com', 'Cenas'),

    ('Brownie de chocolate',
     'Húmedo por dentro y crocante por fuera.',
     E'1. Derretir el chocolate con la manteca.\n2. Agregar azúcar y huevos.\n3. Incorporar la harina con movimientos envolventes.\n4. Hornear 25 minutos a 180 °C.',
     40, '/imagenes/brownie.jpg', interval '10 days', 31, 'lucia@sabornet.com', 'Postres'),

    ('Ensalada caprese',
     'Fresca, simple y lista en minutos.',
     E'1. Cortar los tomates y la mozzarella en rodajas.\n2. Alternar en un plato con hojas de albahaca.\n3. Condimentar con aceite de oliva y sal.',
     10, '/imagenes/caprese.jpg', interval '6 days', 8, 'juan@sabornet.com', 'Ensaladas'),

    ('Sopa de calabaza',
     'Sopa cremosa y reconfortante para días fríos.',
     E'1. Saltear la cebolla en manteca.\n2. Agregar la calabaza en cubos y cubrir con agua.\n3. Cocinar 25 minutos y procesar.\n4. Ajustar la sal y servir caliente.',
     35, '/imagenes/sopa.jpg', interval '3 days', 6, 'maria@sabornet.com', 'Sopas')
) AS r(titulo, descripcion, instrucciones, tiempo, foto, hace, megustas, email, categoria)
JOIN "Usuarios"   u ON u."Email"  = r.email
JOIN "Categorias" c ON c."Nombre" = r.categoria;

