-- Comentarios 
INSERT INTO "comentarios" ("comentario", "fechaCreacion", "UsuarioID", "RecetaID")
SELECT x.comentario, now() - x.hace, u."Id", re."ID"
FROM (VALUES
    ('¡Quedaron riquísimos! Los hice el domingo.',         interval '28 days', 'juan@sabornet.com',  'Panqueques con miel'),
    ('Les agregué un poco de canela y quedaron geniales.', interval '27 days', 'lucia@sabornet.com', 'Panqueques con miel'),
    ('Muy práctica para las mañanas apuradas.',            interval '22 days', 'maria@sabornet.com', 'Tostadas de palta y huevo'),
    ('Crocantes y sin nada de aceite de fritura.',         interval '18 days', 'lucia@sabornet.com', 'Milanesas al horno'),
    ('Mi familia pidió repetir.',                          interval '17 days', 'maria@sabornet.com', 'Milanesas al horno'),
    ('La salsa casera hace toda la diferencia.',           interval '14 days', 'juan@sabornet.com',  'Pasta con salsa de tomate'),
    ('Me quedó un poco seca, bajaría el tiempo de horno.', interval '12 days', 'juan@sabornet.com',  'Tarta de acelga'),
    ('El mejor brownie que probé, súper húmedo.',          interval '8 days',  'maria@sabornet.com', 'Brownie de chocolate'),
    ('Lo hice para una reunión y volaron.',                interval '7 days',  'juan@sabornet.com',  'Brownie de chocolate'),
    ('Simple y deliciosa, ideal para el verano.',          interval '4 days',  'lucia@sabornet.com', 'Ensalada caprese'),
    ('Quedó cremosísima, le sumé un toque de jengibre.',   interval '2 days',  'lucia@sabornet.com', 'Sopa de calabaza')
) AS x(comentario, hace, email, receta)
JOIN "Usuarios" u  ON u."Email"  = x.email
JOIN "Recetas"  re ON re."Titulo" = x.receta;

